-- Fix Data Security numbered list: change <ul> to <ol> and remove manual numbers
UPDATE public.handbook_subsections 
SET content_en = REPLACE(
  content_en,
  '<ul><li>1. change your password every three months and comply with our instructions relating to password security;</li><li>2. use Vipre firewall and spam filter;</li><li>3. comply with our instructions relating to software security and to implement all updates to equipment as soon as you are requested to do so;</li><li>4. encrypt and protect by password, any confidential information held on any personal device or computer;</li><li>5. keep work data and personal data separate on any personal devices used for work purposes;</li><li>6. send work-related emails and messages through our designated communication facilities only;</li><li>7. share data only through our designated systems;</li><li>8. maintain a private space for confidential work calls;</li><li>9. ensure that any display screen equipment is positioned so that only you can see it or a privacy screen is used;</li><li>10. lock your computer terminal whenever it is left unattended;</li><li>11. ensure no one else in your home has access to confidential information stored on our equipment OR your personal computer or other devices;</li><li>12. ensure any wireless network used is secure;</li><li>13. change your wireless network passwords every three months and ensure that your wireless network router has software security updates applied;</li><li>14. keep all papers containing confidential information in filing cabinets that are locked when not in use, and ensure that no one else in your home has access to those papers; and</li><li>15. shred or otherwise dispose securely of confidential information when it is no longer required and at all times comply with our instructions on document retention.</li><li>16. Not to permit any family members or other occupants of your home to view or access company information, documents, records etc.</li></ul>',
  '<ol><li>change your password every three months and comply with our instructions relating to password security;</li><li>use Vipre firewall and spam filter;</li><li>comply with our instructions relating to software security and to implement all updates to equipment as soon as you are requested to do so;</li><li>encrypt and protect by password, any confidential information held on any personal device or computer;</li><li>keep work data and personal data separate on any personal devices used for work purposes;</li><li>send work-related emails and messages through our designated communication facilities only;</li><li>share data only through our designated systems;</li><li>maintain a private space for confidential work calls;</li><li>ensure that any display screen equipment is positioned so that only you can see it or a privacy screen is used;</li><li>lock your computer terminal whenever it is left unattended;</li><li>ensure no one else in your home has access to confidential information stored on our equipment OR your personal computer or other devices;</li><li>ensure any wireless network used is secure;</li><li>change your wireless network passwords every three months and ensure that your wireless network router has software security updates applied;</li><li>keep all papers containing confidential information in filing cabinets that are locked when not in use, and ensure that no one else in your home has access to those papers; and</li><li>shred or otherwise dispose securely of confidential information when it is no longer required and at all times comply with our instructions on document retention.</li><li>not to permit any family members or other occupants of your home to view or access company information, documents, records etc.</li></ol>'
)
WHERE id = '2894b98e-7224-43cf-ac5a-71c403d2dd96';